assert.equal(r(g, u, "2026-03-10T15:30:00Z"), "quiet_hours"); // 00:30 JST 11th
assert.equal(r(g, u, "2026-03-10T23:00:00Z"), null); // 08:00 JST 11th: new local day, cap resets
// UTC day rolled at 09:00 JST; 2 pushes at 08:00 and 10:00 JST same local day must still count together
g = createPushGate();
assert.equal(r(g, u, "2026-03-09T23:00:00Z"), null); // 08:00 JST 10th
assert.equal(r(g, u, "2026-03-10T01:00:00Z"), null); // 10:00 JST 10th
assert.equal(r(g, u, "2026-03-10T02:00:00Z"), "daily_cap_reached");

// blocked attempts do not count; quiet takes precedence
g = createPushGate();
for (let i = 0; i < 5; i++) assert.equal(r(g, u, "2026-03-10T14:00:00Z"), "quiet_hours");
assert.equal(r(g, u, "2026-03-10T03:00:00Z"), null);
assert.equal(r(g, u, "2026-03-10T04:00:00Z"), null);

// independent gates and users; per-call settings
const g2 = createPushGate();
assert.equal(r(g2, u, "2026-03-10T03:00:00Z"), null);
assert.equal(r(g2, { ...u, id: "other" }, "2026-03-10T03:00:00Z"), null);
assert.equal(r(g2, { ...u, dailyCap: 1 }, "2026-03-10T04:00:00Z"), "daily_cap_reached");
assert.equal(r(g2, { ...u, dailyCap: 5 }, "2026-03-10T04:00:00Z"), null);
assert.equal(r(g2, { ...u, dailyCap: 0, id: "z" }, "2026-03-10T04:00:00Z"), "daily_cap_reached");

// non-wrapping quiet window and equal start/end
const ny = { id: "n", timeZone: "America/New_York", quietStart: "13:00", quietEnd: "15:00", dailyCap: 9 };
assert.equal(r(createPushGate(), ny, "2026-01-10T18:30:00Z"), "quiet_hours"); // 13:30 EST
assert.equal(r(createPushGate(), ny, "2026-07-10T18:30:00Z"), null); // 14:30 EDT? -> 14:30 is quiet

assert.equal(r(createPushGate(), ny, "2026-07-10T18:30:00Z"), "quiet_hours"); // 14:30 EDT (DST)
assert.equal(r(createPushGate(), ny, "2026-07-10T20:30:00Z"), null); // 16:30 EDT
assert.equal(r(createPushGate(), { ...ny, quietStart: "08:00", quietEnd: "08:00" }, "2026-07-10T12:00:00Z"), null);

// invalid input fails closed, distinct codes
const gi = createPushGate();
assert.equal(r(gi, { ...u, timeZone: "Mars/Base" }, "2026-03-10T03:00:00Z"), "invalid_settings");
assert.equal(r(gi, { ...u, quietStart: "25:00" }, "2026-03-10T03:00:00Z"), "invalid_settings");
assert.equal(r(gi, { ...u, dailyCap: -1 }, "2026-03-10T03:00:00Z"), "invalid_settings");
assert.equal(gi.attempt(u, new Date("nope")).reason, "invalid_time");
assert.equal(r(gi, u, "2026-03-10T03:00:00Z"), null); // bad calls did not count

console.log("all checks passed");
